INSERT INTO categories(id,name) VALUES (1,'Comunidad'),(2,'Cultura'),(3,'Ciudad');
INSERT INTO news(title,summary,content,category_id,status,published_at) VALUES
('Biblioteca vecinal abre un espacio de lectura compartida','Demostración ficticia: vecinos organizan una sala para intercambiar libros.','Noticia ficticia para uso académico. Una biblioteca imaginaria del valle abre sus puertas a lectores de distintas edades. La actividad propone intercambio de libros y conversaciones sobre historias locales.',1,'published','2026-10-01 09:00:00'),
('Taller de cerámica reúne historias del valle','Demostración ficticia: un taller propone explorar técnicas de cerámica artesanal.','Noticia ficticia para uso académico. Un grupo imaginario de artesanos comparte procesos de creación en barro. Los asistentes preparan pequeñas piezas inspiradas en paisajes del valle del Mantaro.',2,'published','2026-10-02 09:00:00'),
('Huerto comunitario invita a aprender sobre plantas','Demostración ficticia: un huerto educativo ofrece actividades para familias.','Noticia ficticia para uso académico. Un huerto imaginario presenta una jornada de aprendizaje sobre cultivo y cuidado del suelo. Cada visitante puede conversar sobre prácticas de jardinería doméstica.',1,'published','2026-10-03 09:00:00'),
('Muestra de fotografía celebra los paisajes de Huancayo','Demostración ficticia: fotografías inspiradas en la ciudad forman una muestra.','Noticia ficticia para uso académico. Una exposición imaginaria reúne imágenes de calles y montañas. El recorrido invita a observar los cambios de luz y las distintas formas de habitar el paisaje.',2,'published','2026-10-04 09:00:00'),
('Ruta peatonal propone redescubrir plazas de la ciudad','Demostración ficticia: una caminata conecta espacios públicos y relatos urbanos.','Noticia ficticia para uso académico. Una ruta imaginaria enlaza plazas con puntos de descanso. El itinerario se plantea como una conversación sobre el cuidado de los espacios compartidos.',3,'published','2026-10-05 09:00:00'),
('Encuentro musical acerca nuevos talentos al barrio','Demostración ficticia: músicos locales comparten un pequeño encuentro abierto.','Noticia ficticia para uso académico. Un escenario imaginario recibe proyectos musicales del valle. La programación busca que distintas generaciones compartan sus preferencias y experiencias.',2,'published','2026-10-06 09:00:00'),
('Feria de intercambio promueve reutilizar objetos','Demostración ficticia: una feria vecinal intercambia objetos en buen estado.','Noticia ficticia para uso académico. Una feria imaginaria propone recuperar objetos útiles y reducir desperdicios. Sus participantes explican cómo dar una segunda vida a materiales cotidianos.',1,'published','2026-10-07 09:00:00'),
('Jornada de dibujo invita a mirar la arquitectura local','Demostración ficticia: un encuentro de dibujo observa fachadas de la ciudad.','Noticia ficticia para uso académico. Una jornada imaginaria de dibujo conecta observación y memoria urbana. Los participantes registran detalles de edificios y conversan sobre sus formas.',3,'published','2026-10-08 09:00:00'),
('Borrador de demostración: agenda por revisar','Este borrador ficticio debe permanecer oculto para cualquier visitante público.','Contenido ficticio pendiente de revisión. Sirve para comprobar que las rutas públicas no permiten consultar borradores aunque se conozca el identificador.',1,'draft',NULL);
